import{_ as t,o as e,c as s,aj as i}from"./chunks/framework.Cn87zHeG.js";const b=JSON.parse('{"title":"固件版本","description":"","frontmatter":{"title":"固件版本"},"headers":[],"relativePath":"firmware.md","filePath":"firmware.md"}'),n={name:"firmware.md"};function d(r,a,o,l,p,h){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="固件版本" tabindex="-1">固件版本 <a class="header-anchor" href="#固件版本" aria-label="Permalink to &quot;固件版本&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">当前最新整机固件</p><p><strong>1.0.104.261028</strong></p></div><p>本页公布 H1 当前最新整机固件版本，便于开发和排查问题时核对设备状态。设备不会因文档更新而自动升级，实际安装版本请按下方方法查询。</p><h2 id="版本公告" tabindex="-1">版本公告 <a class="header-anchor" href="#版本公告" aria-label="Permalink to &quot;版本公告&quot;">​</a></h2><table tabindex="0"><thead><tr><th>整机固件版本</th><th>说明</th></tr></thead><tbody><tr><td><strong>1.0.104.261028</strong></td><td>当前最新版本；标准版与智能版均使用 ROS 2 Jazzy 和原生 Zenoh（<code>rmw_zenoh_cpp</code>）。电脑端接入见 <a href="./getting-started/communication.html">ROS 2 通信配置</a>。</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">建议更新设备后开始开发</p><p>如果设备使用的是旧固件，建议先升级到最新适配版本，再按 <a href="./getting-started/communication.html#pc-zenoh">Zenoh 通信配置</a>准备开发电脑。升级方法见<a href="./faq/network-ota.html#q17">网络配置与 OTA</a>。</p><p>暂时无法升级的标准版设备，可参考 <a href="./getting-started/communication.html#legacy-dds">Cyclone DDS 兼容说明</a>。</p></div><p>具体功能变更和升级包适用范围以随固件提供的发布说明为准。</p><h2 id="查询设备已安装版本" tabindex="-1">查询设备已安装版本 <a class="header-anchor" href="#查询设备已安装版本" aria-label="Permalink to &quot;查询设备已安装版本&quot;">​</a></h2><p>优先使用<strong>网络配置工具（8080）</strong>：在电脑浏览器打开 <code>http://&lt;机器人IP&gt;:8080</code>，进入 <strong>「状态」→「机器人信息」→「软件版本」</strong>。网线直连时使用 <code>http://10.42.0.2:8080</code>，其他连接方式替换为机器人实际 IP。</p><p>也可以在出厂与跑机测试工具中查看；下面为网线直连时的两个入口：</p><table tabindex="0"><thead><tr><th>工具</th><th>打开地址</th><th>查看位置</th></tr></thead><tbody><tr><td>网络配置工具</td><td><code>http://10.42.0.2:8080</code></td><td>「状态」页 →「机器人信息」→「软件版本」</td></tr><tr><td>出厂与跑机测试工具</td><td><code>http://10.42.0.2:8090</code></td><td>左侧栏底部 →「软件版本」</td></tr></tbody></table><p>两个入口显示的都是机器人已安装的整机软件版本。跑机工具左上角的 <code>v0.1 · run-in</code> 是工具自身标识，不是整机固件版本。</p><h3 id="终端与接口查询-补充" tabindex="-1">终端与接口查询（补充） <a class="header-anchor" href="#终端与接口查询-补充" aria-label="Permalink to &quot;终端与接口查询（补充）&quot;">​</a></h3><p>通过 <a href="./diagnostics/services.html#ssh-login">SSH 远程登录机器人</a>后，也可以在机器人终端执行：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/wlab/robot/VERSION</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>当前版本的预期输出：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1.0.104.261028</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>程序接入可通过网络配置工具的 <code>/api/system</code> 接口读取 <code>data.version</code> 字段：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 将地址替换为机器人的实际地址；下面是网线直连示例</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://10.42.0.2:8080/api/system</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>版本信息未读取到时可能为 <code>null</code>。若接口返回 404 或版本为空，请使用随设备交付的查询方法并联系技术支持。<code>/device_info</code> 的设备标识与整机固件版本是不同信息，不要假定该话题包含 <code>version</code> 或自定义的机器人 ID。报告问题时，请附上设备实际版本及操作步骤。</p><h2 id="升级与版本区别" tabindex="-1">升级与版本区别 <a class="header-anchor" href="#升级与版本区别" aria-label="Permalink to &quot;升级与版本区别&quot;">​</a></h2><p>升级步骤见<a href="./faq/network-ota.html#q17">网络配置与 OTA</a>。请通过技术支持获取适配设备的升级包和发布说明；升级期间保持供电，完成后再次查询版本。</p><p>整机固件版本、<a href="./#更新说明">SDK 文档修订记录</a>、<a href="./hardware/robot-model.html">URDF 模型版本</a>及电机/MCU 固件版本分别管理，不能互相替代。</p>`,23)])])}const m=t(n,[["render",d]]);export{b as __pageData,m as default};
